package com.amdocs.telecom.security; import java.security.SecureRandom; import java.util.concurrent.*; public class OTPService{private static class O{String v;long exp;O(String v){this.v=v;exp=System.currentTimeMillis()+300000;}}private final ConcurrentMap<String,O> m=new ConcurrentHashMap<>();private final SecureRandom r=new SecureRandom();public String issue(String u){String v=String.format("%06d",r.nextInt(1000000));m.put(u,new O(v));return v;}public boolean verify(String u,String v){O o=m.remove(u);return o!=null&&o.exp>System.currentTimeMillis()&&o.v.equals(v);} }
